contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] calldata tos, uint[] calldata vals, address caller) public payable {
        require(tos.length == vals.length && tos.length > 0);
        // caller will attempt to call c.transfer via a low-level call from this contract
        // We can simulate different msg.sender values by having this contract call c.transfer directly;
        // but actual msg.sender seen by c will be this contract. To test caller mismatch we only observe
        // that c.transfer requires msg.sender == c.from(), so calls from this contract should revert unless
        // this contract's address equals c.from(). We therefore record whether call reverts and the return data.

        bool reverted;
        bool returnedTrue;
        // perform call and catch revert
        try c.transfer(tos, vals) returns (bool r) {
            reverted = false;
            returnedTrue = r;
        } catch {
            reverted = true;
            returnedTrue = false;
        }

        // Read the public from address
        address fromAddr = c.from();

        // General rule: if the call did not revert then it must have returned true and the caller (this contract)
        // must be equal to c.from(); conversely, if this contract is not c.from() then the call must revert.
        // This encodes the intended authorization requirement and successful-return property.
        assert((!reverted && returnedTrue && address(this) == fromAddr) || (address(this) != fromAddr && reverted));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] calldata tos, uint[] calldata vals) public payable {
        require(tos.length == vals.length && tos.length > 0);

        bool reverted;
        bool ok;
        try c.transfer(tos, vals) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
            ok = false;
        }

        address fromAddr = c.from();

        // If the call did not revert, it must have returned true and this contract must be the authorized from
        assert((!reverted && ok && address(this) == fromAddr) || reverted);
    }
    receive() external payable {}
}

